import{_ as e,o as s,c as i,a2 as t}from"./chunks/framework.7R1OEGYz.js";const k=JSON.parse('{"title":"Upgrading","description":"","frontmatter":{},"headers":[],"relativePath":"upgrading.md","filePath":"upgrading.md","lastUpdated":1785866144000}'),n={name:"upgrading.md"};function l(h,a,p,r,o,d){return s(),i("div",null,[...a[0]||(a[0]=[t(`<h1 id="upgrading" tabindex="-1">Upgrading <a class="header-anchor" href="#upgrading" aria-label="Permalink to &quot;Upgrading&quot;">​</a></h1><h2 id="the-reuse-values-trap" tabindex="-1">The <code>--reuse-values</code> trap <a class="header-anchor" href="#the-reuse-values-trap" aria-label="Permalink to &quot;The \`--reuse-values\` trap&quot;">​</a></h2><p><code>helm upgrade --reuse-values</code> reuses the values from the last release and merges your new <code>--set</code> flags on top. What it does <strong>not</strong> do is pick up defaults that were added to the chart since that release was installed.</p><p>So when a chart version introduces a new top-level key, an upgrade with <code>--reuse-values</code> leaves that key unset — and any template that reads it unguarded fails:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Error: UPGRADE FAILED: template: open-agenthub/templates/signal-cli.yaml:1:14</span></span>
<span class="line"><span>  executing &quot;open-agenthub/templates/signal-cli.yaml&quot; at &lt;.Values.chat.signal.enabled&gt;:</span></span>
<span class="line"><span>    nil pointer evaluating interface {}.enabled</span></span></code></pre></div><p>The error names the template, not the cause, which makes it a genuinely confusing dead end. Nothing is wrong with your command; the values simply have a hole in them.</p><h3 id="the-fix" tabindex="-1">The fix <a class="header-anchor" href="#the-fix" aria-label="Permalink to &quot;The fix&quot;">​</a></h3><p>Use <code>--reset-then-reuse-values</code> (Helm 3.14 and newer). It resets to the chart defaults and then re-applies the values you supplied, so new keys arrive with their defaults:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">helm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upgrade</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agenthub</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agenthub/open-agenthub</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agenthub</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --reset-then-reuse-values</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chat.telegram.enabled=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span></code></pre></div><h3 id="the-better-fix" tabindex="-1">The better fix <a class="header-anchor" href="#the-better-fix" aria-label="Permalink to &quot;The better fix&quot;">​</a></h3><p>Keep a values file per environment and pass it with <code>-f</code>. Then nothing is implicit:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Export what the release currently has, once</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">helm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agenthub</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> values</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agenthub</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> yaml</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-values.yaml</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Edit it, then from here on</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">helm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upgrade</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agenthub</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agenthub/open-agenthub</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agenthub</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-values.yaml</span></span></code></pre></div><p>That file holds secrets — database password, S3 keys, bot tokens — so keep it out of version control.</p><h2 id="checking-what-an-upgrade-will-change" tabindex="-1">Checking what an upgrade will change <a class="header-anchor" href="#checking-what-an-upgrade-will-change" aria-label="Permalink to &quot;Checking what an upgrade will change&quot;">​</a></h2><p>A chart upgrade brings <em>every</em> change since the version you are on, not just the flag you came for. Render it first and look before you apply:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">helm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upgrade</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agenthub</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agenthub/open-agenthub</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agenthub</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-values.yaml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dry-run=client</span></span></code></pre></div><p>New keys in the rendered ConfigMap are the quickest signal of how far the chart has moved.</p><h2 id="rollouts-and-single-replica-constraints" tabindex="-1">Rollouts and single-replica constraints <a class="header-anchor" href="#rollouts-and-single-replica-constraints" aria-label="Permalink to &quot;Rollouts and single-replica constraints&quot;">​</a></h2><p>The backend defaults to two replicas. Enabling Telegram or Signal forces it to one, because both integrations allow only a single consumer — see <a href="/docs/chat#one-replica-only">Chat integrations</a>. With one replica a rolling update briefly runs the old and new pod at the same time, so expect:</p><ul><li>A short window where the messenger poller logs a conflict. It resolves itself as soon as the old pod terminates.</li><li>No failover while the single pod restarts.</li></ul><p>Neither loses data: Telegram buffers updates by offset for about 24 hours.</p>`,21)])])}const c=e(n,[["render",l]]);export{k as __pageData,c as default};
